#!/usr/bin/env bash
# Grader for one duckdb-2026 ticket (docs/SPEC.md section 5; generated by
# scripts/real_sequence/render_run_sh.py from templates/run_duckdb_sqllogic.sh).
#
# cwd is the grading copy test.sh prepared: the agent's source, with test/
# (the sqllogictest files and the C++ test runner), data/ (test data) and the
# other protected paths taken from the segment's trusted start tree, and this
# ticket's hidden test files overlaid. Nothing else in the copy is trusted.
#
# Build: the copy, without any build/ directory of the agent's, is copied to
# /check (one level below /, like /app; the image's ccache, filled by building
# the bugged base at /app and at /check with base_dir=/, serves every
# unchanged translation unit), configured with the same CMake command
# `GEN=ninja make release` uses, and the unittest target is built. Only files
# that differ from the base recompile; the link always runs.
#
# Tests: build/release/test/unittest runs each fail-to-pass (F2P) and
# pass-to-pass (P2P) test file in a process of its own with a JUnit report. A
# test passes only if its process exits 0 and the report lists it with no
# failure, error or skip (the runner's skip-requirement event counts as a
# skip). A process killed by a signal is a crash of the engine and counts as a
# failure; a timeout, or a missing or unreadable report, counts as an error.
# Exit 0 iff the build succeeds and every test of both groups passes.
# Per-group counts go to $ODYSSEY_OUT/details.json.
set -uo pipefail

TICKET="DDB-02"
F2P=(
    test/optimizer/pushdown/starts_with_pushdown.test
)
P2P=(
    test/sql/function/generic/case_condition.test
    test/optimizer/constant_folding.test
    test/sql/attach/attach_schema.test
    test/sql/copy/parquet/parquet_count_star.test
    test/optimizer/pushdown/table_filter_pushdown.test
    test/sql/optimizer/plan/test_table_filter_pushdown.test
    test/optimizer/pushdown/table_or_pushdown.test
    test/optimizer/filter_pushdown/like_prefix_boundary.test
    test/optimizer/pushdown/scalar_function_pushdown.test
    test/optimizer/pushdown/filter_cannot_pushdown.test
    test/optimizer/regex_to_like_optimizer.test
    test/optimizer/statistics/statistics_varchar.test
    test/optimizer/statistics/statistics_suffix.test
    test/optimizer/statistics/statistics_contains.test
)

JOBS="${ODYSSEY_JOBS:-4}"
TEST_TIMEOUT="${ODYSSEY_TEST_TIMEOUT:-300}"
# The build root is fixed: the test runner's sources embed their source and
# build directories (DUCKDB_ROOT_DIRECTORY, DUCKDB_BUILD_DIRECTORY), and the
# image's ccache holds them compiled for exactly this path.
BUILD_ROOT=/check

src="$(pwd)"
work="$(mktemp -d)"
root=""
cleanup() {
    rm -rf "$work"
    if [ -n "$root" ]; then rm -rf "$root"; fi
}
trap cleanup EXIT
started=$(date +%s)

# ccache settings come from here, not from a config file the agent can edit.
export CCACHE_DIR=/var/cache/ccache CCACHE_BASEDIR=/ CCACHE_NOHASHDIR=1 CCACHE_NODISABLE=1 \
    CCACHE_NOREADONLY=1 CCACHE_NORECACHE=1 CCACHE_CONFIGPATH="$work/ccache.conf"
: > "$work/ccache.conf"
unset CMAKE_C_COMPILER_LAUNCHER CMAKE_CXX_COMPILER_LAUNCHER CMAKE_GENERATOR CMAKE_BUILD_PARALLEL_LEVEL \
    CC CXX CFLAGS CXXFLAGS CPPFLAGS LDFLAGS LD_PRELOAD LD_LIBRARY_PATH

build_status=0
build_step=""
step() {
    # step <name> <command...>: run a build step, keep its log, stop at the first failure.
    build_step="$1"
    shift
    echo "== $TICKET build: $build_step"
    if ! "$@" >"$work/$build_step.log" 2>&1; then
        build_status=1
        tail -n 60 "$work/$build_step.log"
        return 1
    fi
}

prepare() {
    # Copy the source without any build directory of the agent's: the build
    # below always configures a fresh build/release. (Git-ignored files are
    # not deleted wholesale: the repository tracks test data that its own
    # .gitignore matches.)
    root="$BUILD_ROOT" &&
        rm -rf "$root" && mkdir "$root" &&
        (cd "$src" && tar --exclude=./build --exclude=./.git -cf - .) | (cd "$root" && tar -xf -) &&
        rm -rf "$root/build"
}

configure() {
    mkdir -p "$root/build/release" && cd "$root/build/release" &&
        cmake -G "Ninja" -DFORCE_COLORED_OUTPUT=1 -DLOCAL_EXTENSION_REPO="" -DOVERRIDE_GIT_DESCRIBE="" \
            -DDUCKDB_EXPLICIT_VERSION="" -DCMAKE_BUILD_TYPE=Release ../..
}

ccache -z >/dev/null 2>&1
step prepare prepare &&
    step configure configure &&
    step build ninja -C "$root/build/release" -j"$JOBS" unittest
build_secs=$(( $(date +%s) - started ))
ccache -s >"$work/ccache.txt" 2>&1 || true

run_group() {
    # run_group <name> <tests...>: the unittest runner once per test file, so a
    # crash or a hang is charged to the one test that caused it. -f registers
    # exactly the listed file (a missing file is an error).
    local name="$1" i=0 t
    shift
    [ "$build_status" -eq 0 ] || return 0
    echo "== $TICKET $name: $*"
    for t in "$@"; do
        i=$((i + 1))
        printf '%s\n' "$t" >"$work/$name.$i.list"
        (cd "$root" && timeout -k 10 "$TEST_TIMEOUT" build/release/test/unittest \
            --emit-test-events -r junit -o "$work/$name.$i.xml" -f "$work/$name.$i.list") \
            >"$work/$name.$i.log" 2>&1
        echo "$?" >"$work/$name.$i.status"
        echo "   $t: exit $(cat "$work/$name.$i.status")"
    done
}

run_group f2p "${F2P[@]}"
run_group p2p "${P2P[@]}"
total_secs=$(( $(date +%s) - started ))

verdict=0
python3 -I - "$work" "$TICKET" "$build_status" "$build_step" "$build_secs" "$total_secs" \
    "${ODYSSEY_OUT:-}" "${#F2P[@]}" "${F2P[@]}" "${P2P[@]}" <<'PY' || verdict=$?
import json
import re
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

work, ticket = Path(sys.argv[1]), sys.argv[2]
build_status, build_step = int(sys.argv[3]), sys.argv[4]
build_secs, total_secs, out = int(sys.argv[5]), int(sys.argv[6]), sys.argv[7]
n_f2p = int(sys.argv[8])
f2p, p2p = sys.argv[9:9 + n_f2p], sys.argv[9 + n_f2p:]


def outcome(name, index, test):
    """PASS | FAIL | CRASH | SKIP | TIMEOUT | ERROR for one test file's own run."""
    base = work / f"{name}.{index}"
    try:
        status = int((base.parent / (base.name + ".status")).read_text())
    except (OSError, ValueError):
        return "ERROR"
    if status in (124, 137):
        return "TIMEOUT"
    if status >= 128:
        return "CRASH"  # the engine died (signal) while running this test: a failure of the code
    try:
        text = (base.parent / (base.name + ".xml")).read_text(errors="replace")
        # The runner's failure message can carry raw control bytes (a garbled
        # file name), which Catch2 writes unescaped and XML 1.0 forbids.
        text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "?", text)
        root = ET.fromstring(text)
    except (OSError, ET.ParseError):
        return "ERROR"
    cases = [c for c in root.iter("testcase") if c.get("name") == test]
    if len(cases) != 1:
        return "ERROR"
    tags = {child.tag for child in cases[0]}
    log = ""
    try:
        log = (base.parent / (base.name + ".log")).read_text(errors="replace")
    except OSError:
        pass
    if "error" in tags or "failure" in tags:
        return "FAIL"
    if "skipped" in tags or re.search(r'"status":"skip-requirement"', text + log):
        return "SKIP"
    return "PASS" if status == 0 else "ERROR"


def group(name, tests):
    if build_status != 0:
        results = {t: "NOT_BUILT" for t in tests}
    else:
        results = {t: outcome(name, i, t) for i, t in enumerate(tests, 1)}
    passed = sum(r == "PASS" for r in results.values())
    skipped_n = sum(r == "SKIP" for r in results.values())
    failed = sum(r in ("FAIL", "CRASH") for r in results.values())
    errors = len(tests) - passed - skipped_n - failed
    return {"tests": len(tests), "passed": passed, "failed": failed, "errors": errors,
            "skipped": skipped_n, "results": results}


ccache = ""
try:
    ccache = (work / "ccache.txt").read_text(errors="replace")
except OSError:
    pass
hits = re.search(r"Hits:\s+(\d+)\s*/\s*(\d+)", ccache)
groups = {"fail_to_pass": group("f2p", f2p), "pass_to_pass": group("p2p", p2p)}
resolved = build_status == 0 and all(g["passed"] == g["tests"] > 0 for g in groups.values())
details = {"ticket": ticket, "resolved": resolved,
           "build": {"ok": build_status == 0, "failed_step": build_step if build_status else None,
                     "seconds": build_secs,
                     "ccache_hits": f"{hits.group(1)}/{hits.group(2)}" if hits else None},
           "seconds": total_secs, **groups}
if out:
    Path(out).mkdir(parents=True, exist_ok=True)
    (Path(out) / "details.json").write_text(json.dumps(details, indent=2) + "\n")
print(json.dumps({"ticket": ticket, "resolved": resolved, "build_ok": build_status == 0,
                  "build_seconds": build_secs, "seconds": total_secs,
                  "ccache_hits": details["build"]["ccache_hits"],
                  "f2p": groups["fail_to_pass"]["results"],
                  "p2p_not_passed": {t: r for t, r in groups["pass_to_pass"]["results"].items() if r != "PASS"}}))
sys.exit(0 if resolved else 1)
PY

if [ "$verdict" -eq 0 ]; then
    echo "== $TICKET resolved"
    exit 0
fi
echo "== $TICKET not resolved"
exit 1
